var t=[{title:`Soorten bevestiging`,text:`Hefboomstangen voor in een deurkozijn, uitschuifbare spanstangen, vaste wandstangen en plafondstangen worden elk anders geïnstalleerd. Een stang die als “geschikt voor deuropeningen” wordt verkocht, past niet in elke deurlijst, muur of elk kozijn. Sommige typen vragen constructieve bevestiging in stevige steunen, en andere hangen af van een specifieke kozijnvorm.`},{title:`Controleer de classificatie en de constructie`,text:`Lees de instructies en het gewichtslimiet van de fabrikant, inclusief of dynamische bewegingen zijn toegestaan. Reken je volledige lichaamsgewicht plus de extra kracht van zwaaien of trekken mee. Controleer de schroeven, beugels, bekleding en de oppervlakken die de stang raakt of waarbij hij zit. Twijfel je aan de bouwconstructie of de bevestigingsmethode, vraag het dan aan een gekwalificeerde installateur.`},{title:`Test stap voor stap`,text:`Controleer voordat je helemaal gaat hangen of de stang goed vastzit en niet kan draaien, schuiven of verschuiven. Houd je voeten op de vloer en druk er zachtjes en beheerst op. Ga pas door naar een gedeeltelijke hang en daarna een volledige ondersteunde hang als je weet dat de installatie deugt. Een korte test kan niet bewijzen dat beschadigd materiaal of een ongeschikt kozijn veilig is.`},{title:`Veelvoorkomende gevaren`,text:`Bevestig geen banden en doe geen kipping, zwaaiende of verzwaarde pull-ups, tenzij het product daar precies voor is ontworpen en geïnstalleerd. Laat ruimte voor je hoofd, ellebogen en voeten, zonder glas of scherp meubilair in de buurt. Stop met het gebruik van een stang die kraakt, slipt, buigt of loskomt.`},{title:`TrainUp gebruiken`,text:`Markeer in Profiel je optrekstang pas als veilig geïnstalleerd nadat je alles hierboven hebt gecontroleerd. Tot dan laat je schema oefeningen weg die de stang nodig hebben, en trainen rows of bandoefeningen met een veilig anker dezelfde trekbeweging. Ben je beginner, dan zijn ondersteunde hangen, scapulatrekken of ondersteunde pull-ups goede eerste stappen zodra de stang veilig is.`}];var a=[{label:`Mayo Clinic: veiligheid en techniek bij krachttraining`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};